program='''from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            region = []
            queue = deque([(r, c)])
            seen.add((r, c))
            while queue:
                x, y = queue.popleft()
                region.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        queue.append((nx,ny))
            regions.append(region)
    if regions:
        smallest = min(regions, key=len)
        largest = max(regions, key=len)
        for r, c in smallest:
            out[r][c] = 7
        for r, c in largest:
            out[r][c] = 8
    return out
'''
